/*
 * @test
 * @summary JVMS 6.5: the branch-offset boundaries — a conditional branch
 *          (ifeq) whose forward offset is the signed-16-bit maximum +32767,
 *          and goto_w whose 4-byte offset (+32768) exceeds what a 2-byte
 *          branch could encode. The class is generated byte-for-byte at run
 *          time (raw classfile + a hand-written StackMapTable) and loaded
 *          through a fresh class loader.
 *
 *          StackMapTable layout (the subtle part): the split verifier wants a
 *          frame at every *basic-block* start — that is the method entry, every
 *          branch target, and the instruction following every *unconditional*
 *          branch or return (dead code). A conditional branch's fall-through is
 *          part of the same block and needs no frame. So:
 *            - farGoto: goto_w (unconditional) -> frames at offset 5 (the dead
 *              fall-through) AND offset 32768 (the target).
 *            - farIfeq: ifeq (conditional) -> a frame only at its target 32768,
 *              but the nops that pad to the target are dead code after the
 *              fall-through's ireturn, so offset 6 needs a frame too.
 *          Every frame here is same_frame_extended (empty stack, locals
 *          unchanged); the first frame's offset_delta equals its bytecode
 *          offset, subsequent deltas are frame_offset - prev_frame_offset - 1.
 * @run main BranchBoundaryTest
 */

import java.io.ByteArrayOutputStream;
import java.io.DataOutputStream;
import java.net.URL;
import java.net.URLClassLoader;
import java.nio.file.Files;
import java.nio.file.Path;

public class BranchBoundaryTest {
    static int passed;
    static void check(boolean c, String m) { if (c) passed++; else throw new AssertionError(m); }

    static void u1(DataOutputStream d, int v) throws Exception { d.writeByte(v); }
    static void u2(DataOutputStream d, int v) throws Exception { d.writeShort(v); }
    static void u4(DataOutputStream d, long v) throws Exception { d.writeInt((int) v); }
    static void utf8(DataOutputStream d, String s) throws Exception {
        u1(d, 1); byte[] b = s.getBytes("UTF-8"); u2(d, b.length); d.write(b);
    }

    static byte[] build() throws Exception {
        ByteArrayOutputStream o = new ByteArrayOutputStream();
        DataOutputStream d = new DataOutputStream(o);
        d.writeInt(0xCAFEBABE); u2(d, 0); u2(d, 71); // version 71 (JDK 27)

        // constant pool (15 entries, indices 1..14)
        u2(d, 15);
        utf8(d, "BranchBoundaryCls");                       // #1
        u1(d, 7); u2(d, 1);                                 // #2 Class #1
        utf8(d, "java/lang/Object");                        // #3
        u1(d, 7); u2(d, 3);                                 // #4 Class #3
        utf8(d, "<init>");                                  // #5
        utf8(d, "()V");                                     // #6
        utf8(d, "Code");                                    // #7
        utf8(d, "farGoto");                                 // #8
        utf8(d, "()I");                                     // #9
        utf8(d, "StackMapTable");                           // #10
        utf8(d, "farIfeq");                                 // #11
        utf8(d, "(I)I");                                    // #12
        u1(d, 12); u2(d, 5); u2(d, 6);                      // #13 NameAndType #5 #6
        u1(d, 10); u2(d, 4); u2(d, 13);                     // #14 Methodref #4 #13

        u2(d, 0x0021); u2(d, 2); u2(d, 4); u2(d, 0); u2(d, 0); // flags, this, super, ifaces, fields
        u2(d, 3);                                           // methods_count = 3

        // <init>()V
        u2(d, 0x0001); u2(d, 5); u2(d, 6); u2(d, 1);        // flags, name, desc, attrs=1
        u2(d, 7); u4(d, 12 + 5);                            // Code; fixed fields (12) + code (5)
        u2(d, 1); u2(d, 1);                                 // max_stack, max_locals
        u4(d, 5);                                           // code_length
        d.write(new byte[] { 0x2A, (byte) 0xB7, 0x00, 0x0E, (byte) 0xB1 }); // aload_0; invokespecial #14; return
        u2(d, 0); u2(d, 0);                                 // exc_table_len, code_attrs

        // farGoto()I : goto_w +32768 over 32763 nops -> bipush 42
        u2(d, 0x0009); u2(d, 8); u2(d, 9); u2(d, 1);        // public static, name, desc, attrs=1
        int gotoCodeLen = 5 + 32763 + 2 + 1;                // 32771
        u2(d, 7); u4(d, 12 + gotoCodeLen + 14);             // Code; fixed(12)+code+StackMapTable attr(2+4+8=14)
        u2(d, 1); u2(d, 0);                                 // max_stack=1, max_locals=0
        u4(d, gotoCodeLen);
        d.write(0xC8); u4(d, 32768);                        // goto_w +32768
        for (int i = 0; i < 32763; i++) d.write(0x00);      // nops (offsets 5..32767)
        d.write(0x10); d.write(42); d.write(0xAC);          // bipush 42; ireturn (offsets 32768..32770)
        u2(d, 0); u2(d, 1);                                 // exc_table_len, code_attrs=1
        u2(d, 10); u4(d, 8);                                // StackMapTable; 2 entries (u2 count + 2*(u1 type + u2 delta))
        u2(d, 2); d.write(251); u2(d, 5);                   // same_frame_extended @ 5 (goto_w fall-through)
        d.write(251); u2(d, 32762);                         // same_frame_extended @ 32768 (delta=32768-5-1)

        // farIfeq(I)I : ifeq +32767 over 32762 nops -> return 1, else 0
        u2(d, 0x0009); u2(d, 11); u2(d, 12); u2(d, 1);      // public static, name, desc, attrs=1
        int ifCodeLen = 1 + 3 + 1 + 1 + 32762 + 1 + 1;      // 32770
        u2(d, 7); u4(d, 12 + ifCodeLen + 14);
        u2(d, 1); u2(d, 1);                                 // max_stack=1, max_locals=1
        u4(d, ifCodeLen);
        d.write(0x1A);                                      // iload_0
        d.write(0x99); u2(d, 32767);                        // ifeq +32767 (target 1+32767=32768)
        d.write(0x03); d.write(0xAC);                       // iconst_0; ireturn (fall-through, returns 0)
        for (int i = 0; i < 32762; i++) d.write(0x00);      // nops (offsets 6..32767)
        d.write(0x04); d.write(0xAC);                       // iconst_1; ireturn (target 32768, returns 1)
        u2(d, 0); u2(d, 1);                                 // exc_table_len, code_attrs=1
        u2(d, 10); u4(d, 8);                                // StackMapTable; 2 entries
        u2(d, 2); d.write(251); u2(d, 6);                   // same_frame_extended @ 6 (dead code after fall-through return)
        d.write(251); u2(d, 32761);                         // same_frame_extended @ 32768 (delta=32768-6-1)

        u2(d, 0);                                           // class-level attributes_count = 0
        return o.toByteArray();
    }

    static Class<?> load(String name, byte[] b) throws Exception {
        Path dir = Files.createTempDirectory("cls");
        Files.write(dir.resolve(name + ".class"), b);
        URLClassLoader cl = new URLClassLoader(new URL[]{ dir.toUri().toURL() }, null);
        return Class.forName(name, true, cl);
    }

    public static void main(String[] args) throws Exception {
        Class<?> c = load("BranchBoundaryCls", build());
        int far = (Integer) c.getMethod("farGoto").invoke(null);
        check(far == 42, "goto_w with a 4-byte offset +32768 reaches its target");
        int eq = (Integer) c.getMethod("farIfeq", int.class).invoke(null, 0);
        int ne = (Integer) c.getMethod("farIfeq", int.class).invoke(null, 1);
        check(eq == 1 && ne == 0, "ifeq with the 2-byte-maximum offset +32767 branches correctly");
        System.out.println("PASS (" + passed + " assertions)");
    }
}
